begin;
create temporary table wf_test_ids as select gen_random_uuid() manager, gen_random_uuid() worker_a,gen_random_uuid() worker_b,gen_random_uuid() emp_a,gen_random_uuid() emp_b,gen_random_uuid() conv_a,gen_random_uuid() conv_b;
grant select on wf_test_ids to authenticated,anon;
insert into auth.users(id,aud,role,email) select manager,'authenticated','authenticated','wf-manager-'||manager||'@example.com' from wf_test_ids union all select worker_a,'authenticated','authenticated','wf-a-'||worker_a||'@example.com' from wf_test_ids union all select worker_b,'authenticated','authenticated','wf-b-'||worker_b||'@example.com' from wf_test_ids;
insert into public.cqa_managers select manager from wf_test_ids;
insert into public.cqa_employees(id,name,user_id) select emp_a,'Test A',worker_a from wf_test_ids union all select emp_b,'Test B',worker_b from wf_test_ids;
insert into public.cqa_conversations(id,employee_id,fingerprint,name,transcript,checklist,evaluations) select conv_a,emp_a,repeat('a',64),'Test A','[]'::jsonb,'[{"id":"contact","name":"Установление контакта","section":"Начало и понимание запроса","definition":"Оператор поздоровался на языке клиента и представился в первом ответе.","weight":10,"type":"binary","scale":[],"allowNA":false},{"id":"needs","name":"Выявление потребности","section":"Начало и понимание запроса","definition":"Оператор учёл известные детали и уточнил недостающее до ответа. N/A: данных для ответа хватало с самого начала.","weight":15,"type":"binary","scale":[],"allowNA":true},{"id":"identity","name":"Идентификация","section":"Безопасность и решение","definition":"Личность проверена до раскрытия данных или защищённого действия. N/A: запрос не требовал идентификации.","weight":20,"type":"binary","scale":[],"allowNA":true},{"id":"consultation","name":"Корректная и полная консультация","section":"Безопасность и решение","definition":"20: все существенные вопросы закрыты или дан корректный следующий шаг; 15: основной вопрос решён, пропущена второстепенная деталь; 10: существенный вопрос открыт; 5: общая подсказка; 0: нет ответа по существу или ключевая рекомендация ошибочна. N/A: клиент не успел сформулировать запрос.","weight":20,"type":"scale","scale":[0,5,10,15,20],"allowNA":true},{"id":"empathy","name":"Эмпатия и клиентоориентированность","section":"Ведение и завершение","definition":"Оператор вежлив и реагирует на конкретную проблему, если клиент выразил недовольство или описал неудобство.","weight":15,"type":"binary","scale":[],"allowNA":false},{"id":"management","name":"Управление диалогом, скорость и грамотность","section":"Ведение и завершение","definition":"10: ответы ясные и связные, об ожидании предупредили; 7: один заметный сбой; 4: клиент переспрашивает из-за формулировок или порядка ответов; 0: диалог бессвязный или противоречивый. Порог первой реакции в 3 минуты не применяется.","weight":15,"type":"scale","scale":[0,4,7,10],"allowNA":false},{"id":"closing","name":"Завершение","section":"Ведение и завершение","definition":"Оператор подвёл итог или предложил дальнейшую помощь и попрощался. N/A: чат оборвался до возможности завершения.","weight":5,"type":"binary","scale":[],"allowNA":true},{"id":"gross","name":"Грубые ошибки","section":"Грубые нарушения","definition":"Да: выявлено оскорбление клиента, предложение платной услуги в обход компании или раскрытие конфиденциальной информации. Флаг учитывается отдельно от баллов.","weight":0,"type":"flag","scale":[],"allowNA":false}]'::jsonb,'{"contact":{"value":"yes","reason":"В первом ответе есть приветствие и имя оператора.","evidence":["demo-1"],"appeals":[]},"needs":{"value":"na","reason":"Клиент сразу сформулировал запрос; уточнение перед ответом не требовалось.","evidence":["demo-0"],"appeals":[]},"identity":{"value":"na","reason":"Общий вопрос о расположении отчёта не требует доступа к персональным данным.","evidence":["demo-0"],"appeals":[]},"consultation":{"value":15,"reason":"Основной вопрос о скачивании закрыт. Второй вопрос — выбор периода — остался без ответа.","evidence":["demo-0","demo-4"],"appeals":[]},"empathy":{"value":"yes","reason":"Оператор признал конкретное неудобство клиента и предложил помощь.","evidence":["demo-2"],"appeals":[]},"management":{"value":7,"reason":"Ответ понятен, но клиенту пришлось уточнить название раздела. Это один заметный сбой.","evidence":["demo-2","demo-3"],"appeals":[]},"closing":{"value":"yes","reason":"Оператор предложил дальнейшую помощь и попрощался.","evidence":["demo-6"],"appeals":[]},"gross":{"value":"no","reason":"Проверен весь демонстрационный диалог: оскорблений, услуг в обход компании и раскрытия данных не обнаружено.","evidence":["demo-0","demo-6"],"appeals":[]}}'::jsonb from wf_test_ids union all select conv_b,emp_b,repeat('b',64),'Test B','[]'::jsonb,'[{"id":"contact","name":"Установление контакта","section":"Начало и понимание запроса","definition":"Оператор поздоровался на языке клиента и представился в первом ответе.","weight":10,"type":"binary","scale":[],"allowNA":false},{"id":"needs","name":"Выявление потребности","section":"Начало и понимание запроса","definition":"Оператор учёл известные детали и уточнил недостающее до ответа. N/A: данных для ответа хватало с самого начала.","weight":15,"type":"binary","scale":[],"allowNA":true},{"id":"identity","name":"Идентификация","section":"Безопасность и решение","definition":"Личность проверена до раскрытия данных или защищённого действия. N/A: запрос не требовал идентификации.","weight":20,"type":"binary","scale":[],"allowNA":true},{"id":"consultation","name":"Корректная и полная консультация","section":"Безопасность и решение","definition":"20: все существенные вопросы закрыты или дан корректный следующий шаг; 15: основной вопрос решён, пропущена второстепенная деталь; 10: существенный вопрос открыт; 5: общая подсказка; 0: нет ответа по существу или ключевая рекомендация ошибочна. N/A: клиент не успел сформулировать запрос.","weight":20,"type":"scale","scale":[0,5,10,15,20],"allowNA":true},{"id":"empathy","name":"Эмпатия и клиентоориентированность","section":"Ведение и завершение","definition":"Оператор вежлив и реагирует на конкретную проблему, если клиент выразил недовольство или описал неудобство.","weight":15,"type":"binary","scale":[],"allowNA":false},{"id":"management","name":"Управление диалогом, скорость и грамотность","section":"Ведение и завершение","definition":"10: ответы ясные и связные, об ожидании предупредили; 7: один заметный сбой; 4: клиент переспрашивает из-за формулировок или порядка ответов; 0: диалог бессвязный или противоречивый. Порог первой реакции в 3 минуты не применяется.","weight":15,"type":"scale","scale":[0,4,7,10],"allowNA":false},{"id":"closing","name":"Завершение","section":"Ведение и завершение","definition":"Оператор подвёл итог или предложил дальнейшую помощь и попрощался. N/A: чат оборвался до возможности завершения.","weight":5,"type":"binary","scale":[],"allowNA":true},{"id":"gross","name":"Грубые ошибки","section":"Грубые нарушения","definition":"Да: выявлено оскорбление клиента, предложение платной услуги в обход компании или раскрытие конфиденциальной информации. Флаг учитывается отдельно от баллов.","weight":0,"type":"flag","scale":[],"allowNA":false}]'::jsonb,'{"contact":{"value":"yes","reason":"В первом ответе есть приветствие и имя оператора.","evidence":["demo-1"],"appeals":[]},"needs":{"value":"na","reason":"Клиент сразу сформулировал запрос; уточнение перед ответом не требовалось.","evidence":["demo-0"],"appeals":[]},"identity":{"value":"na","reason":"Общий вопрос о расположении отчёта не требует доступа к персональным данным.","evidence":["demo-0"],"appeals":[]},"consultation":{"value":15,"reason":"Основной вопрос о скачивании закрыт. Второй вопрос — выбор периода — остался без ответа.","evidence":["demo-0","demo-4"],"appeals":[]},"empathy":{"value":"yes","reason":"Оператор признал конкретное неудобство клиента и предложил помощь.","evidence":["demo-2"],"appeals":[]},"management":{"value":7,"reason":"Ответ понятен, но клиенту пришлось уточнить название раздела. Это один заметный сбой.","evidence":["demo-2","demo-3"],"appeals":[]},"closing":{"value":"yes","reason":"Оператор предложил дальнейшую помощь и попрощался.","evidence":["demo-6"],"appeals":[]},"gross":{"value":"no","reason":"Проверен весь демонстрационный диалог: оскорблений, услуг в обход компании и раскрытия данных не обнаружено.","evidence":["demo-0","demo-6"],"appeals":[]}}'::jsonb from wf_test_ids;
set local role authenticated;
do $$ begin perform set_config('request.jwt.claims',json_build_object('sub',(select worker_a from wf_test_ids),'role','authenticated')::text,true); end $$;
do $$ declare changed int; begin
 if (select count(*) from public.cqa_employees)<>1 then raise exception 'Employee isolation failed'; end if;
 if (select count(*) from public.cqa_conversations)<>1 then raise exception 'Conversation isolation failed'; end if;
 if (select count(*) from public.cqa_conversations where id=(select conv_b from wf_test_ids))<>0 then raise exception 'Cross-employee detail leaked'; end if;
 if (select count(*) from public.cqa_employee_ratings)<>1 then raise exception 'Rating isolation failed'; end if;
 update public.cqa_conversations set evaluations='{}' where id=(select conv_a from wf_test_ids); get diagnostics changed=row_count;
 if changed<>0 then raise exception 'Worker changed a score'; end if;
 begin insert into public.cqa_managers select worker_a from wf_test_ids; raise exception 'Worker promoted self'; exception when insufficient_privilege then null; end;
 begin perform public.cqa_link_employee((select emp_b from wf_test_ids),'nobody@example.com'); raise exception 'Worker linked another account'; exception when insufficient_privilege then null; end;
 begin insert into public.cqa_appeals(conversation_id,criterion_id,comment,author_id) select conv_b,'consultation','Invalid cross-owner appeal',worker_a from wf_test_ids; raise exception 'Worker appealed another conversation'; exception when insufficient_privilege then null; end;
 insert into public.cqa_appeals(conversation_id,criterion_id,comment,author_id) select conv_a,'consultation','Please reconsider',worker_a from wf_test_ids;
 begin perform public.cqa_resolve_appeal((select id from public.cqa_appeals limit 1),'accepted','20','Should fail'); raise exception 'Worker resolved own appeal'; exception when insufficient_privilege then null; end;
end $$;
do $$ begin perform set_config('request.jwt.claims',json_build_object('sub',(select manager from wf_test_ids),'role','authenticated')::text,true); end $$;
do $$ begin
 if (select count(*) from public.cqa_employees)<>2 then raise exception 'Manager cannot read profiles'; end if;
 if (select score from public.cqa_conversations where id=(select conv_a from wf_test_ids))<>85.38 then raise exception 'Initial DB score incorrect'; end if;
 perform public.cqa_resolve_appeal((select id from public.cqa_appeals where conversation_id=(select conv_a from wf_test_ids)),'accepted','20','The secondary question was answered');
 if (select score from public.cqa_conversations where id=(select conv_a from wf_test_ids))<>93.08 then raise exception 'Appeal did not recalculate DB score'; end if;
 if (select evaluations->'consultation'->>'value' from public.cqa_conversations where id=(select conv_a from wf_test_ids))<>'15' then raise exception 'Original evaluation overwritten'; end if;
 if (select stars from public.cqa_employee_ratings where id=(select emp_a from wf_test_ids))<>4.65 then raise exception 'Stars did not recalculate'; end if;
end $$;
set local role anon;
do $$ begin
 begin perform count(*) from public.cqa_conversations; raise exception 'Anonymous can read conversations'; exception when insufficient_privilege then null; end;
end $$;
reset role;
select 'Workforce RLS passed: own-only profiles/history/ratings, no score edits or privilege escalation, own appeals only, manager resolution, original score retained, stars recalculated, anon denied.' as result;
rollback;